{"content": """"Independent verifier for matches.json.

Re-derives the expected result with a different implementation (character
scanning instead of the boundary-regex approach used by solve.py) and compares
it with the file on disk. Exits non-zero on any mismatch.
"""

import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent

ALNUM = set("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz")
DAYS = {1: 31, 2: 29, 3: 31, 4: 30, 5: 31, 6: 30,
        7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}


def is_ipv4(tok: str) -> bool:
    parts = tok.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit() or len(p) > 3:
            return False
        if len(p) > 1 and p[0] == "0":
            return False
        if int(p) > 255:
            return False
    return True


def is_date(tok: str) -> bool:
    if len(tok) != 10 or tok[4] != "-" or tok[7] != "-":
        return False
    y, m, d = tok[:4], tok[5:7], tok[8:]
    if not (y.isdigit() and m.isdigit() and d.isdigit()):
        return False
    mi, di = int(m), int(d)
    if not 1 <= mi <= 12:
        return False
    return 1 <= di <= DAYS[mi]


def tokens(line: str):
    """Maximal runs of alphanumeric characters (dots/dashes split them)."""
    cur = []
    for ch in line:
        if ch in ALNUM:
            cur.append(ch)
        elif cur:
            yield "".join(cur)
            cur = []
    if cur:
        yield "".join(cur)


def expected() -> list:
    out = []
    for line in (HERE / "log.txt").read_text(encoding="utf-8").splitlines():
        toks = list(tokens(line))
        if not any(is_ipv4(t) for t in toks):
            continue
        dates = [t for t in toks if is_date(t)]
        if dates:
            out.append(dates[-1])
    return out


def main() -> int:
    exp = expected()
    got = json.loads((HERE / "matches.json").read_text(encoding="utf-8"))
    if got != exp:
        print("MISMATCH")
        print("expected:", exp)
        print("actual  :", got)
        return 1
    print("OK", len(got), "matches:", got)
    return 0


if __name__ == "__main__":
    sys.exit(main())
